"use client";

import { motion, useReducedMotion } from "motion/react";
import { useRef, useState } from "react";
import type { ComponentProps, PointerEvent, ReactNode } from "react";

type Ripple = { id: number; x: number; y: number };

export type RipplePrimitiveProps = Omit<ComponentProps<typeof motion.button>, "children" | "onPointerDown"> & {
  children: ReactNode;
};

export function RipplePrimitive({ children, ...props }: RipplePrimitiveProps) {
  const reduceMotion = useReducedMotion();
  const nextId = useRef(0);
  const [ripples, setRipples] = useState<Ripple[]>([]);

  function addRipple(event: PointerEvent<HTMLButtonElement>) {
    const bounds = event.currentTarget.getBoundingClientRect();
    const ripple = { id: nextId.current++, x: event.clientX - bounds.left, y: event.clientY - bounds.top };
    setRipples((current) => [...current, ripple]);
  }

  return (
    <motion.button
      {...props}
      type={props.type ?? "button"}
      onPointerDown={addRipple}
      whileTap={reduceMotion ? undefined : { scale: 0.98 }}
      style={{ ...props.style, position: props.style?.position ?? "relative", overflow: "hidden" }}
    >
      {ripples.map((ripple) => (
        <motion.span
          key={ripple.id}
          aria-hidden="true"
          initial={{ scale: reduceMotion ? 1 : 0, opacity: 0.24 }}
          animate={{ scale: 1, opacity: 0 }}
          transition={{ duration: reduceMotion ? 0.12 : 0.16, ease: "easeOut" }}
          onAnimationComplete={() => setRipples((current) => current.filter((item) => item.id !== ripple.id))}
          style={{ position: "absolute", left: ripple.x, top: ripple.y, width: "220%", aspectRatio: 1, borderRadius: "50%", background: "currentColor", translate: "-50% -50%", pointerEvents: "none" }}
        />
      ))}
      <span style={{ position: "relative" }}>{children}</span>
    </motion.button>
  );
}
